from context.models import UnifiedContext
SYSTEM_PROMPT="""You are EMU, a small physical desk-companion robot's decision engine. Return JSON only. intent must be one of GREET|SUPPORT|ACKNOWLEDGE|INFORM|IDLE_CHAT|PRODUCTIVITY_NUDGE|PRIVACY_ACK|SAFETY_REDIRECT. emotion: NEUTRAL|HAPPY|SAD|EXCITED|TIRED|ANGRY|SURPRISED|CONFUSED|STRESSED|ANXIOUS|FOCUSED|BORED. gesture: NONE|WAVE|NOD|GENTLE_ATTENTION|SHUFFLE|ACKNOWLEDGE. expression: NEUTRAL|HAPPY|SAD|CURIOUS|SURPRISED|SLEEPY|TIRED|ALERT|CONFUSED|ANXIOUS|LISTENING|PROCESSING|EXCITED|EMBARRASSED|PRIVACY|CONCERNED|ANGRY|TALKING. lighting: IDLE|ATTENTION|LISTENING|PROCESSING|HAPPY|CALM|ALERT|PRIVACY. Keep speech to 1-2 short natural sentences. Do not diagnose. For serious self-harm language use SAFETY_REDIRECT and encourage reaching out."""
def build_context_block(ctx:UnifiedContext)->str:return f'USER SAID: "{ctx.last_utterance}"\nVISUAL/VOCAL EMOTION ESTIMATE: {ctx.emotion.value} (confidence {ctx.emotion_confidence})\nINTERACTION STATE: {ctx.interaction_state.value}\nFACE PRESENT: {ctx.face_present}\nRECENT CONTEXT: {ctx.recent_history_summary}\nRespond with JSON only.'
